'use strict'

/**
 * This module encodes and decodes Security+ and Security+ 2.0 rolling and fixed
 * codes, provides utility functions to prepare on-off keying sequences for
 * transmission, and pretty-prints the codes. It can be used to build stand-alone
 * applications.
 * 
 * License: GNU General Public License v3.0 or later
 * Copyright 2016,2020-2024 Clayton Smith (argilo@gmail.com)
 */


function v2CalcParity(cmd) {
  let parity = cmd.fixed.slice(4, 8)
  cmd.data = cmd.data.slice(0, 20).concat(new Bits(4, 0)).concat(cmd.data.slice(24))
  for (let offset = 0; offset < 32; offset += 4) {
    parity ^= cmd.data.slice(offset, offset + 4).value()
  }
  cmd.data = cmd.data.slice(0, 20).concat(new Bits(4, parity)).concat(cmd.data.slice(24))
  return cmd
}

function v2CheckParity(code) {
  let parity = code.fixed.slice(4, 8).value()
  for (let offset = 0; offset < 32; offset += 4) {
    parity ^= code.data.slice(offset, offset + 4).value()
  }
  if (parity !== 0) {
    throw new Error("Parity bits are incorrect")
  }
  code.data = code.data.slice(0, 20).concat(new Bits(4, 0)).concat(code.data.slice(24))
  return code
}

function encodeV2Rolling(code) {
  let rolling = code.rolling.reverse().toBigInt()
  const rollingBase3 = new Array(18).fill(0)
  for (let i = 17; i >= 0; i--) {
    rollingBase3[i] = Number(rolling % 3n)
    rolling = rolling / 3n
  }
  return [{
    rolling: rollingBase3.slice(14, 18).concat(rollingBase3.slice(6, 10)).concat(rollingBase3.slice(1, 2))
  }, {
    rolling: rollingBase3.slice(10, 14).concat(rollingBase3.slice(2, 6)).concat(rollingBase3.slice(0, 1))
  }]
}

function decodeV2Rolling(rolling1, rolling2) {
  const rollingDigits = rolling2.slice(8).concat(rolling1.slice(8))
    .concat(rolling2.slice(4, 8)).concat(rolling1.slice(4, 8))
    .concat(rolling2.slice(0, 4)).concat(rolling1.slice(0, 4))

  let rolling = 0n
  for (const digit of rollingDigits) {
    rolling = (rolling * 3n) + BigInt(digit)
  }
  rolling = new Bits(28, rolling).reverse()
  if (rolling.length > 28) {
    throw new Error("Rolling code was not in expected range")
  }
  return rolling
}

function v2CombineHalves(codes) {
  let code = {}
  code.rolling = decodeV2Rolling(codes[0].rolling, codes[1].rolling)
  code.fixed = codes[0].fixed.concat(codes[1].fixed)
  if (codes[0].data !== undefined) {
    code.data = codes[0].data.concat(codes[1].data)
    code = v2CheckParity(code)
    code = decodeCommand(code)
  }
  return code
}

const ORDER = {
  0b0000: [0, 2, 1],
  0b0001: [2, 0, 1],
  0b0010: [0, 1, 2],
  0b0100: [1, 2, 0],
  0b0101: [1, 0, 2],
  0b0110: [2, 1, 0],
  0b1000: [1, 2, 0],
  0b1001: [2, 1, 0],
  0b1010: [0, 1, 2],
}

const INVERT = {
  0b0000: [true, true, false],
  0b0001: [false, true, false],
  0b0010: [false, false, true],
  0b0100: [true, true, true],
  0b0101: [true, false, true],
  0b0110: [false, true, true],
  0b1000: [true, false, false],
  0b1001: [false, false, false],
  0b1010: [true, false, true],
}

function v2Scramble(indicator, parts) {
  const order = ORDER[indicator.slice(0, 4).value()]
  const invert = INVERT[indicator.slice(4, 8).value()]

  const partsPermuted = order.map(i => parts[i])
  for (let i = 0; i < 3; i++) {
    if (invert[i]) {
      partsPermuted[i] = partsPermuted[i].invert()
    }
  }
  let len = partsPermuted[0].length
  const payload = new Bits(len * 3, 0n)
  for (let i = 0; i < len; i++) {
    payload.setBit((i * 3) + 0, partsPermuted[0].getBit(i))
    payload.setBit((i * 3) + 1, partsPermuted[1].getBit(i))
    payload.setBit((i * 3) + 2, partsPermuted[2].getBit(i))
  }
  return payload
}

function v2Unscramble(indicator, payload) {
  const order = ORDER[indicator.slice(0, 4).value()]
  const invert = INVERT[indicator.slice(4, 8).value()]

  if (order == undefined || invert == undefined) {
    throw new Error("Illegal value for ternary bit")
  }

  //*const order = ORDER[orderKey]
  //*const invert = INVERT[invertKey]

  const partsPermuted = [payload.filter((_, i) => i % 3 === 0), payload.filter((_, i) => i % 3 === 1), payload.filter((_, i) => i % 3 === 2)]
  for (let i = 0; i < 3; i++) {
    if (invert[i]) {
      partsPermuted[i] = partsPermuted[i].invert()
    }
  }

  const parts = [[], [], []]
  for (let i = 0; i < 3; i++) {
    parts[order[i]] = partsPermuted[i]
  }

  return parts
}

function encodeV2HalfParts(code) {
  let indicator = []
  for (const digit of code.rolling.slice(0, 4)) {
    indicator.push(digit >> 1, digit & 1)
  }
  indicator = new Bits(0, indicator)
  code.indicator = indicator

  const parts = [code.fixed.slice(0, 10), code.fixed.slice(10)]
  const parts2 = []
  for (const digit of code.rolling.slice(4)) {
    parts2.push(digit >> 1, digit & 1)
  }


  code.packetType = 0
  if (code.data != undefined) {
    code.packetType = 1
    parts[0] = parts[0].concat(code.data.slice(0, 8))
    parts[1] = parts[1].concat(code.data.slice(8))
    for (const digit of code.rolling.slice(0, 4)) {
      parts2.push(digit >> 1, digit & 1)
    }
  }
  parts.push(new Bits(0, parts2))

  code.payload = v2Scramble(indicator, parts)
  return code
}

function decodeV2HalfParts(packetType, indicator, payload) {
  const payloadLength = packetType === 0 ? 30 : packetType === 1 ? 54 : null
  if (payloadLength === null) {
    throw new Error(packetType === 2 ? "Unsupported packet type" : "Invalid packet type")
  }
  if (payload.length !== payloadLength) {
    throw new Error("Incorrect payload length")
  }

  const parts = v2Unscramble(indicator, payload)

  const rolling = []
  for (let i = 0; i < indicator.length; i += 2) {
    rolling.push((indicator.getBit(i) << 1) | indicator.getBit(i + 1))
  }
  for (let i = 0; i < parts[2].length; i += 2) {
    rolling.push((parts[2].getBit(i) << 1) | parts[2].getBit(i + 1))
  }
  if (rolling.includes(3)) {
    throw new Error("Illegal value for ternary bit")
  }

  const fixed = parts[0].slice(0, 10).concat(parts[1].slice(0, 10))
  let data
  if (packetType === 1) {
    if (rolling.slice(0, 4).join("") !== rolling.slice(-4).join("")) {
      throw new Error("Last four ternary bits do not repeat first four")
    }
    rolling.length -= 4
    data = parts[0].slice(10).concat(parts[1].slice(10))
  }

  return { rolling: rolling, fixed: fixed, data: data }
}

function v2CheckLimits(code) {
  if (code.rolling.length > 28) {
    throw new Error("Rolling code must be less than 2^28")
  }
  if (code.fixed.length > 40) {
    throw new Error("Fixed code must be less than 2^40")
  }
  if ((code.data ?? null) !== null && code.data.length > 32) {
    throw new Error("Data must be less than 2^32")
  }
}

function encodeV2Half(code) {
  code = encodeV2HalfParts(code)
  return ((new Bits(2, code.packetType)).concat(code.indicator)).concat(code.payload)
}

function encodeV2(code) {
  v2CheckLimits(code)

  const codes = encodeV2Rolling(code)
  codes[0].fixed = code.fixed.slice(0, 20)
  codes[1].fixed = code.fixed.slice(20)

  if (code.command != undefined) {
    code = encodeCommand(code)
    code = v2CalcParity(code)
    codes[0].data = code.data.slice(0, 16)
    codes[1].data = code.data.slice(16)
  }

  return [encodeV2Half(codes[0]), encodeV2Half(codes[1])]
}

function decodeV2Half(code) {
  const packetType = code.slice(0, 2).value()
  const indicator = code.slice(2, 10)
  const payload = code.slice(10)
  return decodeV2HalfParts(packetType, indicator, payload)
}

function decodeV2(codes) {
  const hcodes = [decodeV2Half(codes[0]), decodeV2Half(codes[1])]
  return v2CombineHalves(hcodes)
}

function encodeWireline(cmd) {
  v2CheckLimits(cmd)

  const codes = encodeV2Rolling(cmd.rolling)
  codes[0].fixed = cmd.fixed.slice(0, 20)
  codes[1].fixed = cmd.fixed.slice(20)

  cmd = v2CalcParity(cmd)
  codes[0].data = cmd.data.slice(0, 16)
  codes[1].data = cmd.data.slice(16)

  const payloadBits = encodeWirelineHalf(codes[0]).concat(encodeWirelineHalf(codes[1]))
  return new Bits(24, 0x550100).concat(payloadBits)
}

function encodeCommand(code) {
  if (code.fixed.slice(4, 8).value() != 0) {
    throw new Error("When command is provided fixed must be equal device id")
  }
  //code.fixed = code.fixed.slice(0, 4).concat(code.command.slice(0, 4)).concat(code.fixed.slice(8))
  if (code.info) {
    code.data = code.info.slice(12, 20).concat(code.info.slice(4, 12)).concat(code.info.slice(0, 4)).concat(new Bits(4, 0)).concat(code.command.slice(4, 12))
  } else {
    code.data = new Bits(24, 0).concat(code.command.slice(4, 12))
  }
  return code
}


function prettyV2(rolling, fixed, data = null) {
  let result = `Security+ 2.0: rolling=0x${rolling.toString(16).padStart(7, "0")} fixed=0x${fixed.toString(16).padStart(10, "0")} (${fixedPrettyV2(fixed)})`
  if (data !== null) {
    result += ` data=0x${data.toString(16).padStart(8, "0")} (${dataPrettyV2(fixed, data)})`
  }
  return result
}

function fixedPrettyV2(fixed) {
  const button = (fixed >> 32) & 0xf
  const remoteId = fixed & 0xf0ffffffff
  return `button=${button} remote_id=0x${remoteId.toString(16).padStart(10, "0")}`
}

function dataPrettyV2(fixed, data) {
  const button = (fixed >> 32) & 0xf
  const byte1 = data >> 24
  const byte2 = (data >> 16) & 0xff
  const pin = (byte2 << 8) | byte1
  const tail = data & 0xfff

  if (button === 3) {
    return `pin=enter tail=0x${tail.toString(16).padStart(3, "0")}`
  } else {
    const suffix = button === 1 ? "*" : button === 2 ? "#" : ""
    return `pin=${pin.toString().padStart(4, "0")}${suffix} tail=0x${tail.toString(16).padStart(3, "0")}`
  }
}

const WIRELINE_COMMANDS = {
  0x081: "status",
  0x084: "unknown_1",
  0x085: "unknown_2",
  0x0a1: "pair_3_resp",
  0x284: "motor_on",
  0x393: "learn_3_resp",
  0x401: "pair_2_resp",
  0x48c: "openings",
  0x080: "get_status",
  0x0a0: "pair_3",
  0x181: "learn_2",
  0x18c: "lock",
  0x280: "open",
  0x281: "light",
  0x285: "motion",
  0x391: "learn_1",
  0x392: "learn_3",
  0x400: "pair_2",
  0x48b: "get_openings",
}

const DOOR_STATUS = {
  1: "open",
  2: "closed",
  3: "stopped",
  4: "opening",
  5: "closing",
}

function prettyWireline(code) {
  if (code.command != undefined) {
    const command = code.command.value()
    const commandName = WIRELINE_COMMANDS[command] || "<unknown>"
    let msg = ""
    if (command === 0x081) {
      const door = DOOR_STATUS[code.info.slice(0, 4).value()] || "<unknown>"
      const learn = code.info.slice(20).value(15.16)
      const unk1 = code.info.slice(20).value(16, 17)
      const unk2 = code.info.slice(20).value(18, 19)
      const light = code.info.slice(20).value(19, 20)
      const lock = code.info.slice(20).value()
      const blocked = code.info.slice(20).value(6, 7)
      const unk3 = code.info.slice(20).value(7, 8)
      msg = `door=${door} learn=${learn} light=${light} lock=${lock} blocked=${blocked ^ 1} unk1=${unk1} unk2=${unk2} unk3=${unk3}`
    } else if (command === 0x280) {
      msg = (code.info.slice(20).value(12, 13)) ? "pressed" : "released"
    } else if (command === 0x48c) {
      const openings = code.info.slice(4).value()
      msg = `number=${openings}`
    }
    return `rolling=0x${code.rolling.toString(16).padStart(7, "0")} device_id=0x${code.deviceId.toString(16).padStart(10, "0")} command=0x${command.toString(16).padStart(3, "0")} payload=0x${code.info.toString(16).padStart(5, "0")} ${commandName} ${msg}`.trim()
  } else {
    return "No command present"
  }
}


function decodeCommand(code) {
  code.deviceId = code.fixed.slice(0, 4).concat(new Bits(4, 0)).concat(code.fixed.slice(8))
  if (code.data != undefined) {
    code.command = code.fixed.slice(4, 8).concat(code.data.slice(24, 32))
    code.info = code.data.slice(16, 20).concat(code.data.slice(8, 16)).concat(code.data.slice(0, 8))
  }
  return code
}

function encodePigs(code) {
  let parts = encodeV2(codeToBits(code))
  let preamble = new Bits(20, 'f')
  let hex = []
  for (const i in parts) {
    hex.push(new Bits(2, i).concat(parts[i]).concat(new Bits(2, 3)).invert().toString(16))
    parts[i] = preamble.concat(new Bits(2, i)).concat(parts[i]).encodeManchester().toString(2)
  }
  return { pigs: parts, hex: hex }
}
function decodePigs(parts) {
  let decoded = {}
  let codes = []
  for (let part of parts) {
    codes.push((new Bits(0, part.split('').map(Number))).decodeManchester())
  }
  if (codes[0].slice(0, 2).toBigInt() > codes[1].slice(0, 2).toBigInt()) {
    codes = codes.reverse()
  }
  try {
    let len = codes[0].length >= 66 ? 66 : 42
    decoded = codeFromBits(decodeV2([codes[0].slice(2, len), codes[1].slice(2, len)]))
    decoded.codes = [codes[0].invert().concat(new Bits(2, 0)).toString(16), codes[1].invert().concat(new Bits(2, 0)).toString(16)]
  } catch (e) {
    decoded = { err: { msg: e.message, codes: parts[0] + ', ' + parts[1] } }
  }
  return decoded
}

function codeToBits(code) {
  let fldSizes = {
    sequence: 2,
    type: 2,
    indicator: 8,
    payload: 30,
    rolling: 28,
    command: 12,
    data: 32,
    info: 20,
    fixed: 40,
    deviceId: 40,

  }
  let bitcode = {}
  for (const fld in code) {
    if (typeof code[fld] == 'string') {
      if (fldSizes[fld] != undefined) {
        bitcode[fld] = new Bits(fldSizes[fld], code[fld])
      }
    }
  }
  return bitcode
}
function codeFromBits(code) {
  let hexcode = {}
  for (const fld in code) {
    if (code[fld] instanceof Bits) {
      hexcode[fld] = code[fld].toString(16)
    }
  }

  return hexcode
}

/**
 * Exports
 */
module.exports = {
  encodePigs,
  decodePigs,
}


class Bits {
  constructor(length, value = 0n) {
    if (Array.isArray(value)) {
      this.bits = value.map(x => Number(x) != 0 ? 1 : 0)
    } else if (value instanceof Bits) {
      this.bits = value.bits.map(x => Number(x) != 0 ? 1 : 0)
    } else {
      if (Buffer.isBuffer(value)) {
        value = '0x0' + value.toString('hex')
      } else if (typeof value == 'string') {
        value = '0x0' + value
      }
      this.bits = BigInt(value).toString(2).padStart(length, '0').split('').map((x) => x == '0' ? 0 : 1)
    }
  }
  [Symbol.iterator]() {
    return this.bits[Symbol.iterator]()
  }
  toString(radix) {
    return this.toBigInt().toString(radix)
  }
  toBuffer() {
    let buf = []
    let len = (((this.bits.length + 7) / 8) << 0) * 8
    let val = 0
    for (let b = 0; b <= len; b += 1) {
      val = ((val << 1) + (this.bits[b] ?? 0)) & 0xff
      if (b % 8 == 7) buf.push(val)
    }
    return Buffer.from(buf)
  }
  slice(start, end) {
    let bits = this.bits.slice(start, end)
    return new Bits(bits.length, bits)
  }
  reverse() {
    let rvrs = new Bits(this.length, this)
    rvrs.bits.reverse()
    return rvrs
  }
  toBigInt() {
    let value = 0n
    for (const bit of this.bits) {
      value = (value * 2n) + BigInt(bit)
    }
    return value
  }
  encodeManchester() {
    let manc = new Bits(this.length * 2, 0)
    for (const i in this.bits) {
      manc.bits[2 * i] = this.bits[i] == 0 ? 1 : 0
      manc.bits[2 * i + 1] = this.bits[i]
    }
    return manc
  }
  decodeManchester() {
    let bin = []
    for (let i = 0; i < this.length; i += 2) {
      if (this.bits[i] + this.bits[i + 1] != 1)
        break
      else
        bin.push(this.bits[i + 1])
    }
    return new Bits(0, bin)
  }
  value() {
    return Number(this.toBigInt())
  }
  invert() {
    return new Bits(0, this.bits.map((x) => x == 0 ? 1 : 0))
  }
  get length() {
    return this.bits.length
  }
  filter(...args) {
    return new Bits(0, this.bits.filter(...args))
  }
  getBit(n) {
    return this.bits[n] != 0 ? 1 : 0
  }
  setBit(n, value) {
    this.bits[n] = Number(value) != 0 ? 1 : 0
  }
  concat(bits) {
    return new Bits(0, this.bits.concat(bits.bits))
  }
  map(...args) {
    return new Bits(0, this.bits.map(...args))
  }
}


/**
 * Decode then encode and check result same
 */

function unitTest1() {
  console.log('Test 1')
  try {
    let pcodes = { rolling: 'e50062a', fixed: '6f40f22c', command: '81' }
    let test = codeToBits(pcodes)
    let codes = encodePigs(pcodes)
    console.log(codes.pigs)
    console.log(codes.hex)
    const sync = '101010101010101001010101'
    for (let i in codes.pigs) {
      let preamble = codes.pigs[i].indexOf(sync)
      codes.pigs[i] = codes.pigs[i].slice(preamble + sync.length) + '000'
    }
    let code = decodePigs(codes.pigs)
    console.log(codeFromBits(test))
    console.log(code)
    console.log(prettyWireline(codeToBits(code)))
  } catch (e) {
    console.log(e)
  }
}

